import logging
from taf.fdsw.rc.interfaces.FDSW23C.autoconnection import AutoConfiguration23C
from taf.fdsw.rc.schemas.FDSW24B.autoconnection import AutoConnection24B
from taf.fdsw.rc.schemas.FDSW24B.autoconnection_parameters_builder_24b import AutoconnectionParametersBuilder24B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration24B(AutoConfiguration23C):
    param_builder = AutoconnectionParametersBuilder24B

    def __init__(self, client):
        super(AutoConfiguration24B, self).__init__(client)

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        autoconnection_parameters = AutoConnection24B.from_object_dict(data=autoconnection.data)
        return autoconnection_parameters.to_dict()
